// 07 - Queue stress: one producer per core into one bounded queue.
// One suite, one file: it registers itself with the runner; there is no
// list of suites to keep in step with the files.
// GENERATED by micro-os-scaffold (--micro-test-plus).
#include <mtp_board.hpp>
#include "smp_helpers.hpp"

using namespace os::rtos;
using namespace mtp_smp;

namespace
{
  constexpr unsigned stress_messages = 500;
  constexpr unsigned stress_total = ncpu * stress_messages;
  constexpr unsigned stress_words = (stress_messages + 31u) / 32u;

  message_queue_typed<std::uint64_t>* g_stress_queue = nullptr;
  volatile unsigned g_stress_failed = 0;

  void*
  stress_producer (void* arg)
  {
    const unsigned producer = from_arg (arg);
    for (unsigned seq = 0; seq < stress_messages; ++seq)
      {
        const std::uint64_t value
            = (static_cast<std::uint64_t> (producer) << 32) | seq;
        if (g_stress_queue->timed_send (&value, ms (100)) != result::ok)
          {
            store (g_stress_failed, 1u);
            break;
          }
      }
    return nullptr;
  }
} // namespace

mt::static_suite suite_queue_stress{
  "07 - Queue stress", mtp_board::runner (),
  [] (mt::suite& ts) {
    ts.test ("one producer per core, one bounded queue, nothing lost",
             [] (auto& t) {
               message_queue_typed<std::uint64_t> queue{ "mtp-stress-q", 16 };
               g_stress_queue = &queue;
               store (g_stress_failed, 0u);
               thread* threads[ncpu] = {};
               for (unsigned core = 0; core < ncpu; ++core)
                 {
                   threads[core] = spawn ("mtp-stress", stress_producer,
                                          as_arg (core), static_cast<int> (core));
                 }

               static std::uint32_t seen[ncpu][stress_words];
               for (auto& row : seen)
                 {
                   for (auto& word : row)
                     {
                       word = 0;
                     }
                 }
               unsigned received = 0;
               bool clean = true;
               for (unsigned i = 0; i < stress_total; ++i)
                 {
                   std::uint64_t value = 0;
                   if (queue.timed_receive (&value, ms (2000)) != result::ok)
                     {
                       clean = false;
                       break;
                     }
                   const auto producer = static_cast<unsigned> (value >> 32);
                   const auto seq = static_cast<unsigned> (value & 0xffffffffu);
                   if (producer >= ncpu || seq >= stress_messages)
                     {
                       clean = false;
                       continue;
                     }
                   const std::uint32_t bit = 1u << (seq % 32u);
                   if ((seen[producer][seq / 32u] & bit) != 0)
                     {
                       clean = false; // a duplicate
                     }
                   seen[producer][seq / 32u] |= bit;
                   ++received;
                 }
               for (auto* th : threads)
                 {
                   finish (th);
                 }
               unsigned missing = 0;
               for (unsigned producer = 0; producer < ncpu; ++producer)
                 {
                   for (unsigned seq = 0; seq < stress_messages; ++seq)
                     {
                       if ((seen[producer][seq / 32u] & (1u << (seq % 32u))) == 0)
                         {
                           ++missing;
                         }
                     }
                 }
               t.expect (mt::eq (load (g_stress_failed), 0u))
                   << "no producer timed out";
               t.expect (mt::eq (received, stress_total))
                   << fmt ("%u messages received", stress_total);
               t.expect (mt::eq (missing, 0u)) << "each exactly once";
               t.expect (clean) << "no duplicate or malformed message";
             });
  }
};
